  ('usec-bio-013', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Nutrition', 'Digestive system', 1, 'remember', 'ordering', 'Put these parts of the digestive system in the order food passes through them.', '[{"id":"a","text":"Stomach"},{"id":"b","text":"Mouth"},{"id":"c","text":"Large intestine"},{"id":"d","text":"Oesophagus"},{"id":"e","text":"Small intestine"}]'::jsonb, null, 'Trace the path of food through the digestive system.', 'Upper secondary biology: nutrition and digestion (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-eng-001', 1, 'in_review', array['upper_secondary']::text[], 'english', 'Grammar', 'Reported speech', 3, 'apply', 'mcq', 'Change to reported speech: She said, "I am tired."', '[{"id":"a","text":"She said that she was tired."},{"id":"b","text":"She said that I am tired."},{"id":"c","text":"She said that she is being tired."},{"id":"d","text":"She says that she was tired."}]'::jsonb, null, 'Convert direct speech to reported speech.', 'Upper secondary English: reported speech (e.g. KSSM Bahasa Inggeris / CEFR B1–B2).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-eng-002', 1, 'in_review', array['upper_secondary']::text[], 'english', 'Grammar', 'Third conditional', 3, 'apply', 'mcq', 'Which sentence uses the third conditional correctly?', '[{"id":"a","text":"If I had studied, I would have passed."},{"id":"b","text":"If I studied, I would have passed."},{"id":"c","text":"If I would have studied, I would pass."},{"id":"d","text":"If I have studied, I will pass."}]'::jsonb, null, 'Use the third conditional.', 'Upper secondary English: conditionals (e.g. KSSM Bahasa Inggeris / CEFR B2).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-eng-003', 1, 'in_review', array['upper_secondary']::text[], 'english', 'Grammar', 'Passive voice', 3, 'analyze', 'multi_select', 'Select all the sentences that are in the passive voice.', '[{"id":"a","text":"The cake was eaten by the children."},{"id":"b","text":"The letter has been sent."},{"id":"c","text":"She wrote a long letter."},{"id":"d","text":"They are building a new bridge."}]'::jsonb, null, 'Identify the passive voice.', 'Upper secondary English: active and passive voice (e.g. KSSM Bahasa Inggeris / CEFR B1–B2).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-eng-004', 1, 'in_review', array['upper_secondary']::text[], 'english', 'Writing', 'Linking words', 2, 'understand', 'matching', 'Match each linking word to its purpose.', '{"left":[{"id":"a","text":"However"},{"id":"b","text":"Therefore"},{"id":"c","text":"Furthermore"}],"right":[{"id":"x","text":"Adding a point"},{"id":"y","text":"Showing contrast"},{"id":"z","text":"Showing a result"}]}'::jsonb, null, 'Use linking words in writing.', 'Upper secondary English: writing (e.g. KSSM Bahasa Inggeris / SPM).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-eng-005', 1, 'in_review', array['upper_secondary']::text[], 'english', 'Vocabulary', 'Word formation', 2, 'apply', 'short_answer', 'Write the noun form of the verb "decide".', null, null, 'Form nouns from verbs.', 'Upper secondary English: vocabulary (e.g. KSSM Bahasa Inggeris / CEFR B1–B2).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0')
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('lsec-math-036', '{"value":72,"tolerance":0}'::jsonb, '2³ = 8 and 3² = 9, so 8 × 9 = 72.', null, '[{"value":36,"why":"36 comes from 2 × 3 = 6 and 3 × 2 = 6. Powers mean repeated multiplication: 2³ = 2 × 2 × 2 = 8 and 3² = 9."}]'::jsonb),
  ('lsec-math-037', '"a"'::jsonb, 'Collect like terms: 6a − 4a = 2a and 2b + b = 3b.', '{"b":"The 4a is subtracted, not added.","c":"b on its own means 1b, so 2b + b = 3b.","d":"Unlike terms (a and b) cannot be combined into one term."}'::jsonb, null),
  ('lsec-math-038', '{"value":16,"tolerance":0}'::jsonb, 'Subtract 3: x/4 = 4. Multiply by 4: x = 16.', null, '[{"value":1,"why":"Undo ÷ 4 by multiplying by 4, not dividing."},{"value":40,"why":"Subtract the 3 before multiplying: (7 − 3) × 4 = 16."}]'::jsonb),
  ('lsec-math-039', '{"value":5,"tolerance":0}'::jsonb, '5 × 5 × 5 = 125, so the cube root of 125 is 5.', null, '[{"value":25,"why":"25 × 25 × 25 is far more than 125; the cube root is the number that multiplies by itself three times to give 125."}]'::jsonb),
  ('lsec-math-040', '"a"'::jsonb, 'Every point on the y-axis has x-coordinate 0.', '{"b":"(5, 0) has y = 0, so it lies on the x-axis.","c":"(5, 5) is in the first quadrant, away from both axes.","d":"(−5, 5) is in the second quadrant."}'::jsonb, null),
  ('lsec-math-041', '{"value":36,"tolerance":0,"unit":"RM"}'::jsonb, 'There are 2 + 3 = 5 parts, so one part is 60 ÷ 5 = RM12. Raj gets 3 parts: 3 × 12 = RM36.', null, '[{"value":24,"why":"RM24 is Mei''s share (2 parts)."},{"value":20,"why":"Divide by the total number of parts (5), not by 3."}]'::jsonb),
  ('lsec-math-042', '{"value":60,"tolerance":0,"unit":"km/h"}'::jsonb, 'Speed = distance ÷ time = 150 ÷ 2.5 = 60 km/h.', null, '[{"value":375,"why":"375 is distance × time; speed divides distance by time."}]'::jsonb),
  ('lsec-math-043', '["c","d","e"]'::jsonb, 'x + 2 > 5 means x > 3. So 4, 7 and 10 work.', '{"a":"2 + 2 = 4, which is not greater than 5.","b":"3 + 2 = 5, which equals 5 but is not greater than 5."}'::jsonb, null),
  ('lsec-math-044', '"true"'::jsonb, 'C = πd, which is the same as C = 2πr because the diameter is twice the radius.', '{"false":"π is defined as circumference ÷ diameter, so C = πd for every circle."}'::jsonb, null),
  ('lsec-math-045', '["b","d","c","a"]'::jsonb, 'Convert to centimetres: 95 cm, 0.001 km = 100 cm, 1,100 mm = 110 cm, 1.2 m = 120 cm.', null, null),
  ('lsec-sci-026', '"a"'::jsonb, 'The iris is the coloured ring that widens or narrows the pupil: smaller in bright light, bigger in dim light.', '{"b":"The lens focuses light onto the retina.","c":"The retina detects light and forms the image.","d":"The optic nerve carries signals from the retina to the brain."}'::jsonb, null),
  ('lsec-sci-027', '{"value":30,"tolerance":0,"unit":"°"}'::jsonb, 'The law of reflection: the angle of reflection equals the angle of incidence, both measured from the normal.', null, '[{"value":60,"why":"60° is measured from the mirror surface; angles are measured from the normal line."}]'::jsonb),
  ('lsec-sci-028', '["a","b","e"]'::jsonb, 'A mixture contains different substances that are not chemically joined: air (several gases), seawater (water and salts) and soil.', '{"c":"Pure water is a compound: hydrogen and oxygen chemically joined.","d":"Oxygen gas is an element."}'::jsonb, null),
  ('lsec-sci-029', '"true"'::jsonb, 'Light travels in straight lines, which is why shadows form behind opaque objects.', '{"false":"Shadows show that light cannot bend around objects on its own: it travels in straight lines (until it is reflected or refracted)."}'::jsonb, null),
  ('lsec-sci-030', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Filtration traps insoluble solids, distillation boils and condenses the liquid, and chromatography separates dissolved substances that travel at different speeds.', null, null),
  ('lsec-sci-031', '"a"'::jsonb, 'White blood cells protect the body by destroying germs and making antibodies.', '{"b":"Red blood cells carry oxygen.","c":"Platelets help blood to clot.","d":"Plasma carries dissolved food."}'::jsonb, null),
  ('lsec-sci-032', '["b","d","a","c"]'::jsonb, 'Mercury, Venus, Earth, Mars: the four rocky inner planets.', null, null),
  ('lsec-sci-033', '{"accept":["ammeter","an ammeter"]}'::jsonb, 'An ammeter measures current in amperes (A) and is connected in series. A voltmeter measures voltage and is connected in parallel.', null, null),
  ('lsec-hist-001', '"a"'::jsonb, 'Parameswara, a prince from Palembang, founded Melaka around 1400.', '{"b":"Hang Tuah was a famous warrior (laksamana) in Melaka''s later years.","c":"Tun Perak was a great Bendahara who helped Melaka grow.","d":"Sultan Mansur Shah ruled Melaka later, at the height of its power."}'::jsonb, null),
  ('lsec-hist-002', '{"value":1511,"tolerance":0}'::jsonb, 'The Portuguese, led by Alfonso de Albuquerque, captured Melaka in 1511.', null, '[{"value":1641,"why":"1641 is when the Dutch took Melaka from the Portuguese."}]'::jsonb),
  ('lsec-hist-003', '["b","d","a","c"]'::jsonb, 'Melaka Sultanate (from about 1400) → Portuguese (1511) → Dutch (1641) → British (from 1824).', null, null),
  ('lsec-hist-004', '"a"'::jsonb, 'Ancient Egypt depended on the Nile''s yearly floods, which left fertile soil for farming.', '{"b":"Mesopotamia grew between the Tigris and Euphrates rivers.","c":"The Indus Valley civilisation grew along the Indus River.","d":"Early Chinese civilisation grew along the Huang He (Yellow River)."}'::jsonb, null),
  ('lsec-bm-001', '"a"'::jsonb, 'Aur (buluh) menahan tebing daripada runtuh, dan tebing menjadi tempat aur tumbuh. Peribahasa ini bermaksud saling membantu.', '{"b":"Bermusuhan ialah lawan maksud peribahasa ini.","c":"Peribahasa ini tidak berkaitan dengan sifat sombong.","d":"Peribahasa ini tidak berkaitan dengan sifat malas."}'::jsonb, null),
  ('lsec-bm-002', '{"accept":["menulis"]}'::jsonb, 'Awalan meN- + tulis menjadi "menulis" (huruf t digugurkan dan diganti dengan n).', null, null),
  ('lsec-bm-003', '"true"'::jsonb, 'Kata adjektif menerangkan sifat kata nama. "Cantik" menerangkan sifat, contohnya "bunga yang cantik".', '{"false":"\"Cantik\" menerangkan rupa atau sifat sesuatu, jadi ia ialah kata adjektif, bukan kata nama atau kata kerja."}'::jsonb, null),
  ('usec-math-011', '{"value":11,"tolerance":0,"unit":"cm"}'::jsonb, 'Arc length = (θ/360°) × 2πr = (90/360) × 2 × 22/7 × 7 = ¼ × 44 = 11 cm.', null, '[{"value":44,"why":"44 cm is the whole circumference; 90° is a quarter of the circle."},{"value":38.5,"why":"38.5 cm² is the sector''s area, not the arc length."}]'::jsonb),
  ('usec-math-012', '"a"'::jsonb, 'The outcomes are HH, HT, TH, TT. One of four is HH, so P = 1/4 (= 1/2 × 1/2).', '{"b":"1/2 is the chance for one coin; for both, multiply: 1/2 × 1/2.","c":"There are four equally likely outcomes, not three: HT and TH are different.","d":"2/4 is the chance of exactly one head."}'::jsonb, null),
  ('usec-math-013', '{"value":200,"tolerance":0,"unit":"m"}'::jsonb, 'Distance = area under the speed–time graph = 20 × 10 = 200 m.', null, '[{"value":2,"why":"Distance is speed × time, not speed ÷ time."}]'::jsonb),
  ('usec-math-014', '"true"'::jsonb, 'A horizontal line has no vertical change: gradient = rise ÷ run = 0 ÷ run = 0.', '{"false":"A horizontal line does not rise at all, so its gradient is 0. (It is a vertical line whose gradient is undefined.)"}'::jsonb, null),
  ('usec-math-015', '{"value":1,"tolerance":0}'::jsonb, 'In a right-angled isosceles triangle, the opposite and adjacent sides are equal, so tan 45° = opposite ÷ adjacent = 1.', null, '[{"value":0.707,"why":"About 0.707 is sin 45° or cos 45°; tan 45° = 1."}]'::jsonb),
  ('usec-phy-011', '{"value":600,"tolerance":0,"unit":"N"}'::jsonb, 'Weight = mass × gravitational field strength = 60 × 10 = 600 N.', null, '[{"value":60,"why":"60 kg is the mass; weight is a force, W = mg."}]'::jsonb),
  ('usec-phy-012', '"a"'::jsonb, 'A short-sighted eye focuses distant light in front of the retina. A concave lens spreads the light out so it focuses on the retina.', '{"b":"A convex lens corrects long-sightedness (hypermetropia).","c":"A mirror reflects light; it cannot be worn to focus vision.","d":"A prism bends and splits light; it does not correct focus."}'::jsonb, null),
  ('usec-phy-013', '{"value":84000,"tolerance":0,"unit":"J"}'::jsonb, 'Q = mcθ = 2 × 4,200 × 10 = 84,000 J.', null, '[{"value":42000,"why":"Include the mass: 2 kg doubles the energy needed."},{"value":8400,"why":"Include the temperature rise: × 10 °C."}]'::jsonb),
  ('usec-phy-014', '["a","b","d"]'::jsonb, 'Joules, kilowatt-hours (used on electricity bills) and electronvolts (used in atomic physics) all measure energy.', '{"c":"The watt measures power: energy per second.","e":"The newton measures force."}'::jsonb, null),
  ('usec-phy-015', '"false"'::jsonb, 'A transformer needs a changing magnetic field to induce a voltage in the secondary coil. Steady d.c. makes a constant field, so nothing is induced.', '{"true":"Induction needs a changing magnetic field, which only alternating current provides continuously."}'::jsonb, null),
  ('usec-chem-011', '"a"'::jsonb, 'A strong acid ionises completely in water. Hydrochloric acid does; the others only partly ionise.', '{"b":"Ethanoic acid (in vinegar) is a weak acid.","c":"Carbonic acid (in fizzy drinks) is a weak acid.","d":"Citric acid (in citrus fruit) is a weak acid."}'::jsonb, null),
  ('usec-chem-012', '{"value":10,"tolerance":0}'::jsonb, 'Na⁺ forms when a sodium atom loses one electron: 11 − 1 = 10.', null, '[{"value":12,"why":"A positive ion has lost electrons, not gained them."}]'::jsonb),
  ('usec-chem-013', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Bronze is mostly copper (with tin), steel is mostly iron (with carbon), duralumin is mostly aluminium (with copper and other metals).', null, null),
  ('usec-chem-014', '["b","d","a","c"]'::jsonb, 'Potassium reacts violently with water, magnesium burns brightly, iron rusts slowly and copper is quite unreactive.', null, null),
  ('usec-chem-015', '{"accept":["water","H2O"]}'::jsonb, 'Neutralisation: acid + alkali → salt + water. For example, HCl + NaOH → NaCl + H₂O.', null, null),
  ('usec-bio-009', '"a"'::jsonb, 'Ribosomes join amino acids together to build proteins, following instructions carried by mRNA.', '{"b":"The nucleus holds the DNA instructions but does not assemble proteins.","c":"The Golgi apparatus modifies and packages proteins after they are made.","d":"Vacuoles store water and substances."}'::jsonb, null),
  ('usec-bio-010', '{"value":46,"tolerance":0}'::jsonb, 'Human body cells have 46 chromosomes in 23 pairs. Sperm and egg cells have 23.', null, '[{"value":23,"why":"23 is the number of pairs, or the number in a sperm or egg cell."}]'::jsonb),
  ('usec-bio-011', '["a","b","d"]'::jsonb, 'Abiotic factors are physical and chemical conditions: temperature, light and soil pH.', '{"c":"Predators are living, so they are a biotic factor.","e":"Bacteria are living organisms: a biotic factor."}'::jsonb, null),
  ('usec-bio-012', '"false"'::jsonb, 'Arteries carry blood at high pressure straight from the heart, so they have thick, muscular, elastic walls. Veins carry blood at low pressure and have thinner walls.', '{"true":"It is the other way round: high pressure in arteries needs thick walls."}'::jsonb, null),
  ('usec-bio-013', '["b","d","a","e","c"]'::jsonb, 'Mouth → oesophagus → stomach → small intestine (most absorption) → large intestine (water absorbed).', null, null),
  ('usec-eng-001', '"a"'::jsonb, 'In reported speech after "said", the tense usually moves back (am → was) and the pronoun changes (I → she).', '{"b":"The pronoun must change: she is talking about herself, so \"I\" becomes \"she\".","c":"\"Is being tired\" is not natural English; the tense moves back to \"was\".","d":"The reporting verb should stay in the past: she said."}'::jsonb, null),
  ('usec-eng-002', '"a"'::jsonb, 'The third conditional talks about an imagined past: If + past perfect (had studied), would have + past participle (would have passed).', '{"b":"The if-clause needs the past perfect: had studied.","c":"\"Would\" does not go in the if-clause.","d":"This mixes present perfect and future; it is not a past regret."}'::jsonb, null),
  ('usec-eng-003', '["a","b"]'::jsonb, 'Passive sentences use a form of "be" + past participle, and the subject receives the action: was eaten, has been sent.', '{"c":"\"She wrote\" is active: the subject does the action.","d":"\"They are building\" is active (present continuous)."}'::jsonb, null),
  ('usec-eng-004', '{"a":"y","b":"z","c":"x"}'::jsonb, '"However" introduces a contrast, "therefore" a result, and "furthermore" an additional point.', null, null),
  ('usec-eng-005', '{"accept":["decision"]}'::jsonb, 'decide (verb) → decision (noun): "It was a difficult decision."', null, null)
